#!/usr/bin/env python3
"""omics/spatial_deconvolution — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "omics"
SKILL = "spatial_deconvolution"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'spatial_deconvolution', 'matrix_path': '', 'n_cells_post_qc': 0, 'cluster_sizes': {}, 'marker_genes_per_cluster': {}, 'umap_png': '', 'diagnostics': {'brain': 'omics', 'archetype': 'omics_scrna'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Cell2location 空间转录组 cell type deconvolution。host_env=praxis-omics。
    第一版只跑 reference signature fitting + abundance estimation 简单流程。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    spatial_h5ad = payload.get("spatial_h5ad") or payload.get("visium_h5ad")
    ref_h5ad = payload.get("reference_scrna_h5ad")
    cell_type_col = payload.get("cell_type_col", "cell_type")
    out_h5ad = payload.get("out_h5ad") or _tempfile.NamedTemporaryFile(suffix="_c2l.h5ad", delete=False).name
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "cell2location", "out_h5ad": out_h5ad}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "matrix_path": "", "n_cells_post_qc": 0,
                "cluster_sizes": {}, "marker_genes_per_cluster": {}, "umap_png": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not spatial_h5ad or not _os.path.isfile(spatial_h5ad):
        return {"ok": False, "error": "需要 spatial_h5ad (Visium)", "diagnostics": diagnostics}
    if not ref_h5ad or not _os.path.isfile(ref_h5ad):
        return {"ok": False, "error": "需要 reference_scrna_h5ad", "diagnostics": diagnostics}
    script = (
        "import json, sys, scanpy as sc\n"
        "import cell2location\n"
        "from cell2location.models import RegressionModel, Cell2location\n"
        f"sp = sc.read_h5ad({spatial_h5ad!r}); ref = sc.read_h5ad({ref_h5ad!r})\n"
        f"ct_col = {cell_type_col!r}\n"
        "# 1) 训练 reference signature (CPU 用 max_epochs 少)\n"
        "RegressionModel.setup_anndata(adata=ref, labels_key=ct_col)\n"
        "mod_ref = RegressionModel(ref)\n"
        "mod_ref.train(max_epochs=50, batch_size=2500, train_size=1, lr=0.002)\n"
        "ref = mod_ref.export_posterior(ref, sample_kwargs={'num_samples': 50})\n"
        "inf_aver = ref.varm['means_per_cluster_mu_fg']\n"
        "# 2) Cell2location on spatial\n"
        "Cell2location.setup_anndata(adata=sp)\n"
        "mod_sp = Cell2location(sp, cell_state_df=inf_aver, N_cells_per_location=5, detection_alpha=20)\n"
        "mod_sp.train(max_epochs=300, batch_size=None, train_size=1)\n"
        "sp = mod_sp.export_posterior(sp, sample_kwargs={'num_samples': 50})\n"
        f"sp.write_h5ad({out_h5ad!r})\n"
        "ct_cols = [c for c in sp.obsm.get('q05_cell_abundance_w_sf', sp.obs).columns if hasattr(sp.obsm.get('q05_cell_abundance_w_sf'),'columns')] if 'q05_cell_abundance_w_sf' in sp.obsm else []\n"
        f"json.dump({{'matrix_path': {out_h5ad!r}, 'n_cells_post_qc': int(sp.n_obs),\n"
        "           'cluster_sizes': {}, 'marker_genes_per_cluster': {},\n"
        "           'n_cell_types': len(ct_cols)}}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 7200)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "cell2location 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed, "umap_png": "",
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
